Unit Test Code:
#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_show_list_empty_list(void) {
    // Setup: head is NULL to trigger the path where loop is not entered
    node *head = NULL;

    // Capture stdout to verify the function prints the header and nothing else
    FILE *original_stdout = stdout;
    FILE *temp_stream = tmpfile();
    if (temp_stream == NULL) {
        TEST_FAIL_MESSAGE("Failed to create temporary file for stdout capture");
    }
    stdout = temp_stream;

    // Test: call show_list with NULL head
    show_list(head);

    // Stop capture and get output
    rewind(temp_stream);
    fseek(temp_stream, 0, SEEK_END);
    long output_size = ftell(temp_stream);
    rewind(temp_stream);
    char *output = malloc(output_size + 1);
    if (output == NULL) {
        TEST_FAIL_MESSAGE("Failed to allocate memory for captured output");
    }
    fread(output, 1, output_size, temp_stream);
    output[output_size] = '\0';
    stdout = original_stdout;
    fclose(temp_stream);
    TEST_ASSERT_NOT_NULL(output);

    // Assertions: verify the output matches expected
    // The function prints the header line, then exits loop because head is NULL
    const char *expected = "Process Priority AT BT CT TAT WT 
";
    TEST_ASSERT_EQUAL_STRING(expected, output);

    // Cleanup
    free(output);
    // No need to free head because it's NULL
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_show_list_empty_list);
    return UNITY_END();
}

